import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F
import pickle
from torch_geometric.nn import GATv2Conv

class LightTrafficGAT(nn.Module):
    def __init__(self, num_nodes, pretrained_path, graph_path, device, state_dim=60, action_dim=12, output_dim=4, dropout=0.1):
        super().__init__()
        self.dropout = dropout
        self.num_of_interactions = num_nodes
        self.device = device
        self.proj_lane, self.proj_phase = self.get_encoder_proj(num_nodes)

        self._build_lane_reverse_mapping()

        state_emb_dim = 64
        action_emb_dim = 64

        self.state_encoder = nn.Sequential(
            nn.Linear(state_dim, state_emb_dim),
            nn.ReLU(),
            nn.Dropout(dropout)
        )

        self.action_encoder = nn.Sequential(
            nn.Linear(action_dim, action_emb_dim),
            nn.ReLU(),
            nn.Dropout(dropout)
        )

        in_channels = state_emb_dim + action_emb_dim
        hidden_channels = 128

        self.gat1 = GATv2Conv(in_channels, hidden_channels, heads=2, concat=True)
        self.gat2 = GATv2Conv(hidden_channels * 2, hidden_channels, heads=1, concat=False)

        self.predictor = nn.Sequential(
            nn.Linear(hidden_channels, 128),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(128, 64),
            nn.ReLU(),
            nn.Linear(64, output_dim)
        )

        self.load_weights(pretrained_path, device)
        self.edge_index = self.load_edge(graph_path, device)

